async def act(page):
    import re
    # 1) Try to dismiss any modal/dialog/pop-up that could block the complementary or main regions.
    # Try common close-button patterns first (aria-name containing close / × / x).
    try:
        close_candidates = page.get_by_role("button", name=re.compile(r"close|×|x", re.IGNORECASE))
        if await close_candidates.count() > 0:
            await close_candidates.first.click()
    except Exception:
        # ignore and continue to other strategies
        pass

    # If there is a dialog role, try to click the first button inside it as a fallback.
    try:
        dialogs = page.get_by_role("dialog")
        if await dialogs.count() > 0:
            for i in range(await dialogs.count()):
                dialog = dialogs.nth(i)
                btns = dialog.get_by_role("button")
                if await btns.count() > 0:
                    await btns.nth(0).click()
                    break
    except Exception:
        pass

    # 2) Locate the complementary region (the site's search area) and the search input.
    complementary = page.get_by_role("complementary")

    # Prefer role=searchbox named "Search", fall back to a textbox named "Search" inside the same complementary region.
    search_input = None
    try:
        # Attempt preferred locator
        candidate = complementary.get_by_role("searchbox", name="Search")
        if await candidate.count() > 0:
            search_input = candidate
        else:
            raise Exception("no searchbox")
    except Exception:
        # fallback
        candidate = complementary.get_by_role("textbox", name="Search")
        if await candidate.count() > 0:
            search_input = candidate
        else:
            # Final fallback: any textbox inside complementary
            candidate = complementary.get_by_role("textbox")
            if await candidate.count() > 0:
                search_input = candidate
            else:
                raise Exception("Could not locate a search input inside the complementary region")

    # 3) Fill the search input with the keyword 'crypto'.
    await search_input.fill("crypto")

    # 4) Find and activate the search control inside complementary.
    # Prefer a button with name containing 'search', otherwise click the first button in complementary,
    # otherwise press Enter in the search input.
    try:
        search_button = complementary.get_by_role("button", name=re.compile(r"search", re.IGNORECASE))
        if await search_button.count() > 0:
            await search_button.first.click()
        else:
            # fallback to the first button in complementary if present
            first_btn = complementary.get_by_role("button")
            if await first_btn.count() > 0:
                await first_btn.first.click()
            else:
                # final fallback: press Enter in the input
                await search_input.press("Enter")
    except Exception:
        # As a last resort, press Enter in the input
        try:
            await search_input.press("Enter")
        except Exception as e:
            raise

    # 5) Wait for results to appear in role='main'. Use a locator wait first, then networkidle as a fallback.
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        await page.wait_for_load_state("networkidle")

    # 6) Locate article results inside main and compute the third-to-last index safely.
    main = page.get_by_role("main")
    articles = main.get_by_role("article")
    article_count = await articles.count()
    if article_count < 3:
        raise Exception(f"Expected at least 3 search results but found {article_count}")

    target_index = article_count - 3
    target_article = articles.nth(target_index)

    # 7) Click the article's heading link if present, otherwise click the first link inside the article.
    # Preference: article -> heading -> link
    heading_count = await target_article.get_by_role("heading").count()
    clicked = False
    if heading_count > 0:
        heading = target_article.get_by_role("heading").nth(0)
        heading_link = heading.get_by_role("link")
        if await heading_link.count() > 0:
            await heading_link.nth(0).click()
            clicked = True

    if not clicked:
        # Fallback: first link inside the article
        links = target_article.get_by_role("link")
        if await links.count() == 0:
            raise Exception("No clickable link found inside the target article")
        await links.nth(0).click()

    # Note: The last action is a navigation click; act() ends here.

